syntax:
// Prototype (declaration): header + semicolon, no body
return_type function_name(parameter_types);

double circleArea(double r);   // names are optional:
bool isEven(int);              // also valid

int main() {
    // ... calls circleArea(...) and isEven(...)
    return 0;
}

// Definition: header + body, parameter names required
double circleArea(double r) {
    return 3.14159 * r * r;
}

sample.code:
#include <iostream>
using namespace std;

// Prototypes
double circleArea(double r);
bool isEven(int n);

int main() {
    cout << "Area = " << circleArea(3) << endl;
    cout << "8 is " << (isEven(8) ? "even" : "odd") << endl;
    return 0;
}

// Definitions
double circleArea(double r) {
    return 3.14159 * r * r;
}

bool isEven(int n) {
    return n % 2 == 0;
}

#include <iostream>
using namespace std;

double total(double, int);
void printLine(int);

int main() {
    double t = total(120.5, 4);
    printLine(20);
    cout << "Total = " << t << endl;
    return 0;
}

double total(double price, int qty) {
    return price * qty;
}

void printLine(int n) {
    for (int i = 0; i < n; i++) {
        cout << "-";
    }
    cout << endl;
}

#include <iostream>
using namespace std;

int higher(int a, int b);
bool isPass(int marks);

int main() {
    int m1, m2;
    cin >> m1 >> m2;
    int best = higher(m1, m2);
    cout << "Higher: " << best << endl;
    if (isPass(best)) {
        cout << "Pass" << endl;
    } else {
        cout << "Fail" << endl;
    }
    return 0;
}

int higher(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}

bool isPass(int marks) {
    return marks >= 50;
}

